  // ── Live 1-Second Timer for Papers Screen ──
  startPapersTimer(container, sessions) {
    if (this.papersInterval) clearInterval(this.papersInterval);
    this.papersInterval = setInterval(() => {
      const now = Date.now();
      container.querySelectorAll(".timer-pkg-span").forEach((span) => {
        const startIso = span.dataset.start;
        if (startIso) {
          const elapsed = Math.floor((now - new Date(startIso).getTime()) / 1e3);
          const remaining = Math.max(0, 600 - elapsed);
          const m2 = Math.floor(remaining / 60).toString().padStart(2, "0");
          const s2 = (remaining % 60).toString().padStart(2, "0");
          span.textContent = `${m2}:${s2}`;
        }
      });
      container.querySelectorAll(".timer-upcoming-span").forEach((span) => {
        const targetIso = span.dataset.target;
        if (targetIso) {
          const diff = Math.max(0, new Date(targetIso).getTime() - now);
          const h = Math.floor(diff / (1e3 * 3600)).toString().padStart(2, "0");
          const m2 = Math.floor(diff / (1e3 * 60) % 60).toString().padStart(2, "0");
          const s2 = Math.floor(diff / 1e3 % 60).toString().padStart(2, "0");
          span.textContent = `${h} : ${m2} : ${s2}`;
        }
      });
    }, 1e3);
  }
