    const escapeHTML = (value) => String(value ?? "").replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char]);
    const formatDate = (value) => new Date(value).toLocaleString(void 0, { year: "numeric", month: "long", day: "2-digit", hour: "2-digit", minute: "2-digit" });
